#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_3.md ]] || { echo 'Run in your repository root after the third Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_FOUR'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/discover/discover_screen.dart': '',
'desktop/hyper_player/lib/discover/android_browse.dart': '',
'desktop/hyper_player/lib/screens/search_screen.dart': '',
'desktop/hyper_player/test/search_discover_visual_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_4.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Home Search and Discover browsing installed. Android unchanged.')
VISUAL_GROUP_FOUR
